From e9d2749c747bb65181ad2085ed2306e82698fa87 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:43:05 +0100
Subject: [PATCH] applets/timer: scroll the hovered digit in the compact view

Scrolling over the time in the panel or a small desktop timer always
changed the seconds, wherever the pointer was. The wheel now finds the
digit under the pointer and steps it, like the full view's digits do.

BUG: 461285
---
 applets/timer/CompactRepresentation.qml | 35 ++++++++++++++++++++++---
 1 file changed, 32 insertions(+), 3 deletions(-)

diff --git a/applets/timer/CompactRepresentation.qml b/applets/timer/CompactRepresentation.qml
index bf61fe7b6..366f66beb 100644
--- a/applets/timer/CompactRepresentation.qml
+++ b/applets/timer/CompactRepresentation.qml
@@ -68,8 +68,7 @@ Item {
     Keys.onLeftPressed: event => handleKeyPress(event, !running && isVertical && inPanel, Application.layoutDirection === Qt.RightToLeft)
     Keys.onRightPressed: event => handleKeyPress(event, !running && isVertical && inPanel, Application.layoutDirection !== Qt.RightToLeft)

-    function adjustTime(value) {
-        const stepsize = Plasmoid.configuration.showSeconds ? 1 : 60
+    function adjustTime(value, stepsize = Plasmoid.configuration.showSeconds ? 1 : 60) {
         while (value >= 15 && compactRepresentation.seconds + stepsize < 24*60*60) {
             compactRepresentation.adjustTimerRequested(stepsize)
             value -= 15;
@@ -82,11 +81,14 @@ Item {
     }

     WheelHandler {
+        id: wheelHandler
         acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
         enabled: !compactRepresentation.running
         onWheel: event => {
             event.accepted = true;
-            rotation = compactRepresentation.adjustTime(rotation);
+            const pos = compactRepresentation.mapToItem(remainingTimeLabel, wheelHandler.point.position);
+            const stepsize = remainingTimeLabel.digitStepAt(pos.x, pos.y);
+            rotation = stepsize > 0 ? compactRepresentation.adjustTime(rotation, stepsize) : compactRepresentation.adjustTime(rotation);
         }
     }

@@ -214,6 +216,33 @@ Item {
                 Layout.maximumWidth: Math.max(Plasmoid.configuration.showTitle && titleLabel.implicitWidth, implicitWidth, Plasmoid.configuration.showProgressBar && remainingTimeProgressBar.implicitWidth)
                 visible: Plasmoid.configuration.showRemainingTime

+                // seconds represented by each character of "hh:mm:ss"
+                readonly property list<int> digitSteps: [36000, 3600, 0, 600, 60, 0, 10, 1]
+
+                function digitStepAt(x: real, y: real) : int {
+                    if (!visible || truncated || y < 0 || y >= height) {
+                        return 0;
+                    }
+                    let left = 0;
+                    if (effectiveHorizontalAlignment === Text.AlignHCenter) {
+                        left = (width - contentWidth) / 2;
+                    } else if (effectiveHorizontalAlignment === Text.AlignRight) {
+                        left = width - contentWidth;
+                    }
+                    const offset = (x - left) / contentWidth * digitMetrics.advanceWidth(text);
+                    for (let i = 0; i < text.length; ++i) {
+                        if (offset >= digitMetrics.advanceWidth(text.slice(0, i)) && offset < digitMetrics.advanceWidth(text.slice(0, i + 1))) {
+                            return digitSteps[i];
+                        }
+                    }
+                    return 0;
+                }
+
+                FontMetrics {
+                    id: digitMetrics
+                    font: remainingTimeLabel.font
+                }
+
                 TextMetrics {
                     id: textMetrics
                     // make it not jump around: reserve space for one extra digit than reasonable
-- 
